{
  "headline": "Air Quality Alert: Protect Your Home Environment",
  "summary": "Current air quality is unhealthy with an AQI of {{aqi.now}}. Focus on sealing your indoor space and timing ventilation carefully to protect the seniors and cardiac-sensitive members of your household.",
  "cards": [
    {
      "actionId": "close_windows_at_peak",
      "title": "Seal Your Home During Peak Hours",
      "why": "With outdoor levels at {{pm25.now}}, keeping windows shut prevents pollutants from entering your living space.",
      "when": "Keep closed especially between {{avoid.start}}:00 and {{avoid.end}}:00.",
      "steps": [
        "Close all windows and balcony doors.",
        "Use weather stripping on drafty frames.",
        "Keep exhaust fans off unless cooking."
      ]
    },
    {
      "actionId": "air_house_in_best_window",
      "title": "Ventilate During Best Window",
      "why": "Briefly airing out the house when levels are lowest helps reduce indoor CO2 and trapped pollutants.",
      "when": "Open windows between {{best.start}}:00 and {{best.end}}:00.",
      "steps": [
        "Open windows for a short duration only.",
        "Use cross-ventilation if possible.",
        "Close immediately after the window ends."
      ]
    },
    {
      "actionId": "damp_mop_dont_sweep",
      "title": "Damp Mop Instead of Sweeping",
      "why": "Sweeping kicks up settled dust and PM2.5 particles into the air, which can irritate sensitive respiratory systems.",
      "when": "Daily cleaning routine.",
      "steps": [
        "Use a damp cloth or mop for floors.",
        "Avoid using dry brooms or feather dusters.",
        "Wipe surfaces with a wet microfiber cloth."
      ]
    },
    {
      "actionId": "cooking_ventilation",
      "title": "Maximize Kitchen Ventilation",
      "why": "Cooking creates significant indoor PM2.5. Proper ventilation is critical to prevent levels from spiking indoors.",
      "when": "Every time you cook.",
      "steps": [
        "Turn on the chimney or exhaust fan.",
        "Open a nearby window slightly for airflow.",
        "Keep the kitchen door closed."
      ]
    },
    {
      "actionId": "errands_in_best_window",
      "title": "Schedule Errands Wisely",
      "why": "Reducing outdoor exposure for seniors and those with cardiac conditions is vital when the AQI is {{aqi.now}}.",
      "when": "Plan trips between {{best.start}}:00 and {{best.end}}:00.",
      "steps": [
        "Combine all necessary trips into one.",
        "Avoid outdoor activity during {{avoid.start}}:00–{{avoid.end}}:00.",
        "Check local air quality before leaving."
      ]
    },
    {
      "actionId": "warmth_without_burning",
      "title": "Choose Clean Heating Methods",
      "why": "Burning wood or biomass for warmth drastically increases indoor pollution, which is dangerous for cardiac health.",
      "when": "Whenever heating is required.",
      "steps": [
        "Use electric heaters or warm blankets.",
        "Avoid open fires or coal heaters.",
        "Ensure heaters are well-maintained."
      ]
    }
  ],
  "memberNotes": [
    {
      "group": "senior",
      "note": "Seniors are at higher risk; ensure they remain indoors and avoid any physical exertion during high pollution hours."
    },
    {
      "group": "cardiac",
      "note": "For the family member with cardiac conditions, minimizing exposure is essential to prevent strain on the heart."
    }
  ],
  "tradeoffs": [
    "Closing windows reduces fresh air; use a fan to circulate indoor air if it feels stuffy.",
    "Damp mopping requires more effort than sweeping but significantly lowers airborne dust levels."
  ]
}

